import re
import os
expression = re.compile(r'file(\d+)\.txt')
for item in os.scandir():
    if item.is_file():
        match = expression.match(item.name)
        if match:
            num = int(match.group(1))
            if num < 1900:
                num += 2000
                new_name = f"file{num}.txt"
                os.rename(item.name, new_name)

