def recursive(n):
    if n == 0:
        return 1
    else:
        return recursive(n - 1) + recursive(n - 1)
def recursive_incremental(n):
    if n == 0:
        return 1
    else:
        return recursive_incremental(n - 1) + recursive_incremental(n - 1)
